\title{The Even Harmonic Strength of Antipodal Spherical Designs}
\author{Aristotle}
\date{2026-07-04}

\begin{document}

\begin{abstract}
We study the \emph{harmonic strength} of a finite set of points $X$ on the unit
sphere in $\R^n$ --- the set of degrees $k$ for which every homogeneous harmonic
polynomial of degree $k$ averages to zero over $X$. We prove two foundational
structural facts about \textbf{antipodal} sets (sets closed under negation,
$X = -X$). First, for an antipodal set every odd degree automatically lies in the
harmonic strength; consequently the harmonic strength of an antipodal set is an
infinite subset of $\N$. This is dimension-free and needs no metric hypothesis:
it follows from the parity law $p(-x) = (-1)^k p(x)$ together with the pairing
$x \leftrightarrow -x$. Second, we give a complete analysis of degree $2$:
membership of degree $2$ is equivalent to isotropy of the moment matrix
$M_{ij} = \sum_{x} x_i x_j$, i.e. $M = (|X|/n) I$ (equivalently, $X$ is a tight
frame), and this is exactly the equality case of the degree-$2$ Welch/Sidelnikov
bound $\sum_{x,y} \inner{x}{y}^2 \ge |X|^2/n$. These results reduce the theory to
its even part and motivate the central conjecture: for an antipodal set, if any
even degree lies in the harmonic strength, then degree $2$ does too.
\end{abstract}

\maketitle

\section{Introduction}

Distributing points evenly on a sphere arises across mathematics, physics, and
engineering. The theory of \emph{spherical designs} of Delsarte, Goethals, and
Seidel makes ``evenly'' precise: a finite set $X$ on the unit sphere
$S^{n-1} \subset \R^n$ is a spherical $t$-design if the average of every
polynomial of degree at most $t$ over $X$ equals its average over the whole
sphere. A graded refinement replaces the threshold $t$ by the full
\emph{harmonic strength}: the set of individual degrees $k$ at which $X$
integrates harmonic polynomials exactly.

This paper concerns antipodal sets, $X = -X$ (cross-polytopes, root systems,
opposite-pole configurations). Our contributions: (1) for antipodal $X$ every
odd degree lies in the harmonic strength (Theorem~\ref{thm:oddfree}), whence the
harmonic strength is infinite (Theorem~\ref{thm:infinite}); (2) degree $2$ lies
in the harmonic strength iff the moment matrix is a scalar multiple of the
identity (Theorem~\ref{thm:iso}); (3) the degree-$2$ Welch bound holds with
equality precisely under this isotropy condition (Theorem~\ref{thm:welch}).
Together these concentrate all nontrivial content in the even degrees and expose
degree $2$ as the fundamental even constraint.

\section{Definitions}

Throughout $n \ge 1$ and we work with real polynomials in $x_1, \dots, x_n$;
$\inner{x}{y} = \sum_i x_i y_i$ and $|X|$ denotes cardinality.

\begin{definition}[Laplacian]
The \emph{Laplace operator} is $\Delta p = \sum_{i=1}^n \partial^2 p / \partial x_i^2$.
\end{definition}

\begin{definition}[Harmonic polynomial]
A polynomial $p$ is \emph{harmonic} if $\Delta p = 0$.
\end{definition}

\begin{definition}[Homogeneous polynomial]
A polynomial $p$ is \emph{homogeneous of degree $k$} if $p(\lambda x) = \lambda^k p(x)$
for all scalars $\lambda$.
\end{definition}

\begin{definition}[Harmonic strength]
Let $X \subset \R^n$ be finite. A degree $k \in \N$ lies in the \emph{harmonic
strength} $\Hst(X)$ if every homogeneous harmonic polynomial $p$ of degree $k$
satisfies $\sum_{x \in X} p(x) = 0$.
\end{definition}

\begin{definition}[Antipodal set]
A finite set $X \subset \R^n$ is \emph{antipodal} if $-x \in X$ whenever
$x \in X$; equivalently $X = -X$.
\end{definition}

\begin{definition}[Moment matrix]
For finite $X \subset \R^n$, the \emph{moment matrix} is the symmetric
$n \times n$ matrix $M_{ij} = \sum_{x \in X} x_i x_j$.
\end{definition}

\begin{remark}
$X$ is a spherical $t$-design iff $\{1, 2, \dots, t\} \subseteq \Hst(X)$. The
sphere hypothesis is used only through the normalization $|x| = 1$ in Section~4.
\end{remark}

\section{Odd degrees and infinite harmonic strength}

\begin{lemma}[Parity under negation]\label{lem:parity}
If $p$ is homogeneous of degree $k$, then $p(-x) = (-1)^k p(x)$ for all $x$.
\end{lemma}

\begin{proof}
Evaluation is additive over monomials, so treat a single monomial
$c \prod_i x_i^{d_i}$ with $\sum_i d_i = k$. Substituting $-x$ multiplies it by
$(-1)^{\sum_i d_i} = (-1)^k$. Summing over the monomials of $p$, all of total
degree $k$ by homogeneity, gives $p(-x) = (-1)^k p(x)$.
\end{proof}

\begin{lemma}[Negation invariance]\label{lem:bij}
If $X$ is antipodal, $x \mapsto -x$ is a bijection of $X$ onto itself.
\end{lemma}

\begin{proof}
Negation is an involution, hence injective, and maps $X$ into $X$; an injection
of a finite set into itself is a bijection.
\end{proof}

\begin{corollary}[Odd forms sum to zero]\label{cor:odd}
If $X$ is antipodal and $p$ is homogeneous of odd degree $k$, then
$\sum_{x \in X} p(x) = 0$.
\end{corollary}

\begin{proof}
By Lemma~\ref{lem:parity}, $p(-x) = -p(x)$. Reindexing by the bijection
$x \mapsto -x$ of Lemma~\ref{lem:bij},
$\sum_x p(x) = \sum_x p(-x) = -\sum_x p(x)$, so the sum is zero.
\end{proof}

\begin{theorem}[Odd degrees are free]\label{thm:oddfree}
For any antipodal finite $X \subset \R^n$ and any odd $k \in \N$, $k \in \Hst(X)$.
\end{theorem}

\begin{proof}
Let $p$ be homogeneous harmonic of degree $k$. Harmonicity is not needed: by
Corollary~\ref{cor:odd}, homogeneity of odd degree plus antipodality forces
$\sum_x p(x) = 0$. As this holds for all such $p$, $k \in \Hst(X)$.
\end{proof}

\begin{theorem}[Infinite harmonic strength]\label{thm:infinite}
For any antipodal finite $X \subset \R^n$, $\Hst(X)$ is infinite.
\end{theorem}

\begin{proof}
The injection $m \mapsto 2m+1$ has image the odd numbers, all in $\Hst(X)$ by
Theorem~\ref{thm:oddfree}; hence $\Hst(X)$ contains an infinite set.
\end{proof}

\begin{remark}
Theorem~\ref{thm:oddfree} uses no sphere, no dimension bound, and no harmonicity
--- only that negation is an involution and the parity law. All genuine geometry
lives in the even degrees.
\end{remark}

\section{Degree two: isotropy and the Welch bound}

Assume now $|x| = 1$ for all $x \in X$, so $\sum_i x_i^2 = 1$ and
\begin{equation}\label{eq:trace}
\tr M = \sum_{i=1}^n M_{ii} = \sum_{x \in X} \sum_{i=1}^n x_i^2 = |X|.
\end{equation}

A homogeneous quadratic $q(x) = \sum_{i \le j} a_{ij} x_i x_j$ has
$\Delta q = 2 \sum_i a_{ii}$, so $q$ is harmonic iff it is traceless; the
harmonic quadratics are spanned by $X_i X_j$ ($i \neq j$) and $X_i^2 - X_j^2$.

\begin{lemma}[Sum of a harmonic quadratic is a trace]\label{lem:tr}
For symmetric $A$ and $q_A(x) = \sum_{i,j} A_{ij} x_i x_j$,
$\sum_{x \in X} q_A(x) = \sum_{i,j} A_{ij} M_{ij} = \tr(AM)$.
\end{lemma}

\begin{proof}
Exchange summation order:
$\sum_x \sum_{i,j} A_{ij} x_i x_j = \sum_{i,j} A_{ij} \sum_x x_i x_j
= \sum_{i,j} A_{ij} M_{ij} = \tr(AM)$.
\end{proof}

\begin{theorem}[Degree two equals isotropy]\label{thm:iso}
Let $X$ lie on the unit sphere of $\R^n$. Then $2 \in \Hst(X)$ if and only if
$M = (|X|/n) I$, i.e. $M_{ij} = 0$ for $i \neq j$ and $M_{ii} = |X|/n$ for all $i$.
\end{theorem}

\begin{proof}
($\Leftarrow$) If $M = cI$, then for traceless $A$, Lemma~\ref{lem:tr} gives
$\sum_x q_A(x) = c \tr(A) = 0$; all harmonic quadratics sum to zero.

($\Rightarrow$) Testing $2 \in \Hst(X)$ against $X_i X_j$ ($i \neq j$) yields
$M_{ij} = 0$; against $X_i^2 - X_j^2$ yields $M_{ii} = M_{jj}$. So $M = cI$, and
by \eqref{eq:trace}, $nc = |X|$, i.e. $c = |X|/n$.
\end{proof}

\begin{remark}
$M = (|X|/n) I$ says $X$ is a \emph{tight frame}:
$\sum_x \inner{x}{u}^2 = (|X|/n)|u|^2$ for every $u$, i.e. isotropy with no
preferred axis.
\end{remark}

\begin{lemma}[Energy equals moment-square sum]\label{lem:energy}
For finite $X \subset \R^n$, $\sum_{x,y \in X} \inner{x}{y}^2 = \sum_{i,j} M_{ij}^2$.
\end{lemma}

\begin{proof}
Expand $\inner{x}{y}^2 = \sum_{i,j} x_i x_j y_i y_j$ and separate the independent
sums over $x$ and $y$:
$\sum_{x,y} \inner{x}{y}^2 = \sum_{i,j}(\sum_x x_i x_j)(\sum_y y_i y_j)
= \sum_{i,j} M_{ij}^2$.
\end{proof}

\begin{theorem}[Degree-two Welch/Sidelnikov bound]\label{thm:welch}
Let $X$ lie on the unit sphere of $\R^n$. Then
\[
\sum_{x \in X}\sum_{y \in X} \inner{x}{y}^2 \ \ge\ \frac{|X|^2}{n},
\]
with equality if and only if $2 \in \Hst(X)$.
\end{theorem}

\begin{proof}
By Lemma~\ref{lem:energy} the left side is $\sum_{i,j} M_{ij}^2$. Then
\[
\sum_{i,j} M_{ij}^2 = \sum_i M_{ii}^2 + \sum_{i\neq j} M_{ij}^2 \ \ge\ \sum_i M_{ii}^2
\ \ge\ \frac{1}{n}\Big(\sum_i M_{ii}\Big)^2 = \frac{(\tr M)^2}{n} = \frac{|X|^2}{n},
\]
the middle step by Cauchy--Schwarz and the last by \eqref{eq:trace}. Equality
requires $M_{ij} = 0$ ($i \neq j$) and all $M_{ii}$ equal, i.e. $M = (|X|/n)I$,
which by Theorem~\ref{thm:iso} is $2 \in \Hst(X)$; the converse is immediate.
\end{proof}

\begin{remark}
Theorem~\ref{thm:welch} exhibits degree $2$ as the fundamental even constraint:
the first even degree whose moment functional is bounded below, saturated exactly
by designs containing $2$ in their harmonic strength. It is the base rung of a
tower of higher even Welch/Sidelnikov bounds.
\end{remark}

\section{The central conjecture}

\begin{conjecture}[Even strength contains 2]\label{conj:main}
Let $X$ be a finite antipodal set on the unit sphere of $\R^n$ with $n \ge 3$
(dimension $d = n-1 \ge 2$). If some even integer belongs to $\Hst(X)$, then
$2 \in \Hst(X)$.
\end{conjecture}

Equivalently, the even part of the harmonic strength of an antipodal design, if
nonempty, always begins at $2$. The mechanism: membership of an even degree $2m$
is equivalent to the vanishing of a Gegenbauer moment, a weighted average of
$C_{2m}^{\lambda}(\inner{x}{y})$ over ordered pairs. The even Gegenbauer
polynomials form a positive-definite family whose moments are coupled by the
inner-product distribution of $X$, so a higher even moment cannot vanish while
the degree-$2$ moment stays positive (a strict degree-$2$ Welch bound).
Saturating a higher even bound should force the base rung, degree $2$, to be
saturated as well. Theorem~\ref{thm:welch} makes this base case fully explicit,
reducing the conjecture to propagating it upward through the Gegenbauer
hierarchy.

\section{Applications}

\begin{itemize}
\item \textbf{Cubature.} $\{1,\dots,t\} \subseteq \Hst(X)$ integrates degree-$\le t$
polynomials exactly; antipodality supplies all odd degrees for free.
\item \textbf{Tight frames.} Theorem~\ref{thm:iso} identifies degree-$2$ designs
with tight frames and Theorem~\ref{thm:welch} with Welch-equality codebooks
(low-coherence ensembles in communications and compressed sensing).
\item \textbf{Quantum measurement.} Rank-one tight informationally complete
measurements are exactly tight frames; isotropy is their resolution of identity.
\item \textbf{Energy minimization.} The Welch bound is the degree-$2$ universal
lower bound on pairwise potential energy.
\end{itemize}

\section{Discussion and future work}

The harmonic strength of an antipodal spherical set splits cleanly: odd degrees
are automatic and infinite, while the even degrees hold all geometric content,
anchored by a fully understood degree $2$. Next steps: (1) prove
Conjecture~\ref{conj:main} by propagating the degree-$2$ base case through the
Gegenbauer hierarchy; (2) establish the full even Welch tower and classify its
equality cases; (3) relate the length of the even strength to the number of
distinct inner-product values of $X$; (4) sharpen Theorem~\ref{thm:iso} into a
rigidity statement identifying antipodal sets whose even strength begins at $2$
with tight frames. Antipodal symmetry both gives (every odd degree) and
constrains (the even degrees, earned from $2$ upward).

\end{document}

