"""Searching for antipodal degree-2 designs (isotropic tight frames).

A random antipodal set is generically NOT isotropic.  This demo runs a simple
projected-gradient flow that minimizes the Welch defect  E(X) - |X|^2/n  and shows
it converges to 0, i.e. to a configuration with 2 in its harmonic strength.
"""
from __future__ import annotations
import math, random
from typing import List, Sequence, Tuple

Vector = List[float]

def dot(x: Sequence[float], y: Sequence[float]) -> float:
    return sum(a * b for a, b in zip(x, y))

def normalize(x: Vector) -> Vector:
    nrm = math.sqrt(dot(x, x))
    return [c / nrm for c in x]

def welch_defect(pairs: List[Vector], n: int) -> float:
    X = pairs + [[-c for c in v] for v in pairs]
    E = sum(dot(x, y) ** 2 for x in X for y in X)
    return E - len(X) ** 2 / n

def flow(n: int, npairs: int, steps: int = 4000, lr: float = 0.01,
         seed: int = 3) -> Tuple[List[Vector], float]:
    rng = random.Random(seed)
    pairs = [normalize([rng.gauss(0, 1) for _ in range(n)]) for _ in range(npairs)]
    for _ in range(steps):
        # gradient of E over the +half (each pair contributes symmetrically)
        grads = [[0.0] * n for _ in range(npairs)]
        for a in range(npairs):
            for b in range(npairs):
                c = dot(pairs[a], pairs[b])
                for i in range(n):
                    grads[a][i] += 8.0 * c * pairs[b][i]
        for a in range(npairs):
            pairs[a] = normalize([pairs[a][i] - lr * grads[a][i] / npairs
                                  for i in range(n)])
    return pairs, welch_defect(pairs, n)

def main() -> None:
    for (n, npairs) in [(2, 3), (3, 4), (4, 6)]:
        _, d = flow(n, npairs)
        print(f"n={n}, {npairs} antipodal pairs -> final Welch defect = {d:.3e}")

if __name__ == "__main__":
    main()

